package com.cowave.search.indices.service

import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch.core.search.SourceConfig
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.indices.dto.AnalyzeRequest
import com.cowave.search.indices.dto.AnalyzeResponse
import com.cowave.search.indices.dto.AnalyzeToken
import com.cowave.search.indices.dto.DocumentSearchRequest
import com.cowave.search.indices.dto.DocumentSearchResponse
import com.cowave.search.indices.dto.IndexInfo
import com.cowave.search.indices.dto.IndexMappingResponse
import com.cowave.search.indices.dto.IndexSettingsResponse
import com.cowave.search.indices.dto.OpenPitResponse
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class IndicesService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(IndicesService::class.java)

    // ── 인덱스 목록 조회 ──────────────────────────────────────────────────

    fun listIndices(
        clusterId: String,
        pattern: String = "*",
        excludeSystem: Boolean = true,
    ): List<IndexInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val statsResponse = client.indices().stats { it.index(pattern) }
            val aliasResponse =
                runCatching {
                    client.indices().getAlias { it.index(pattern) }
                }.getOrNull()

            statsResponse.indices()?.mapNotNull { (indexName, indexStats) ->
                if (excludeSystem && indexName.startsWith(".")) return@mapNotNull null

                val aliases =
                    aliasResponse
                        ?.aliases()
                        ?.get(indexName)
                        ?.aliases()
                        ?.keys
                        ?.toList() ?: emptyList()

                IndexInfo(
                    name = indexName,
                    health = null,
                    status = null,
                    docsCount = indexStats.total()?.docs()?.count(),
                    storeSizeBytes = indexStats.total()?.store()?.sizeInBytes(),
                    primaryShards = null,
                    replicaShards = null,
                    aliases = aliases,
                )
            } ?: emptyList()
        }.getOrElse { e ->
            logger.warn("인덱스 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    // ── 문서 조회 (Search After + PIT) ───────────────────────────────────

    fun searchDocuments(
        clusterId: String,
        indexName: String,
        request: DocumentSearchRequest,
    ): DocumentSearchResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            client.search(
                { s ->
                    s.index(indexName)
                        .size(request.size)
                        .source(SourceConfig.of { it.fetch(true) })
                        .apply {
                            if (request.pitId != null) {
                                pit { p -> p.id(request.pitId).keepAlive { t -> t.time("1m") } }
                            } else {
                                from(request.from)
                            }
                            request.query?.let { q ->
                                query { qb -> qb.withJson(q.toJsonReader()) }
                            }
                            if (request.sort != null) {
                                request.sort.forEach { sortItem ->
                                    sortItem.forEach { (field, order) ->
                                        sort { so ->
                                            so.field { f ->
                                                f.field(field)
                                                    .order(
                                                        if (order.toString().uppercase() == "DESC") {
                                                            SortOrder.Desc
                                                        } else {
                                                            SortOrder.Asc
                                                        },
                                                    )
                                            }
                                        }
                                    }
                                }
                            }
                            request.searchAfter?.let { sa ->
                                searchAfter(
                                    sa.map { v ->
                                        co.elastic.clients.elasticsearch._types.FieldValue.of(v.toString())
                                    },
                                )
                            }
                        }
                },
                Map::class.java,
            )

        val hits = response.hits().hits()
        val documents =
            hits.map { hit ->
                @Suppress("UNCHECKED_CAST")
                (hit.source() as? Map<String, Any?> ?: emptyMap<String, Any?>()).plus("_id" to hit.id())
            }
        val lastSearchAfter = hits.lastOrNull()?.sort()?.map { it._get() }

        return DocumentSearchResponse(
            total = response.hits().total()?.value() ?: 0L,
            hits = documents,
            pitId = response.pitId(),
            searchAfter = lastSearchAfter,
        )
    }

    // ── PIT 관리 ─────────────────────────────────────────────────────────

    fun openPit(
        clusterId: String,
        indexName: String,
        keepAlive: String = "5m",
    ): OpenPitResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.openPointInTime { it.index(indexName).keepAlive { t -> t.time(keepAlive) } }
        return OpenPitResponse(pitId = response.id())
    }

    fun closePit(
        clusterId: String,
        pitId: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        runCatching {
            client.closePointInTime { it.id(pitId) }
        }.onFailure { e ->
            logger.warn("PIT 닫기 실패 [{}]: {}", pitId, e.message)
        }
    }

    // ── 분석기 실행 ───────────────────────────────────────────────────────

    fun analyze(
        clusterId: String,
        request: AnalyzeRequest,
    ): AnalyzeResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            if (request.index != null) {
                client.indices().analyze { a ->
                    a.index(request.index)
                        .text(request.text)
                        .apply {
                            request.analyzer?.let { analyzer(it) }
                            request.tokenizer?.let { tokenizer { t -> t.name(it) } }
                            request.filter?.let { filter(it) }
                            request.charFilter?.let { charFilter(it) }
                        }
                }
            } else {
                client.indices().analyze { a ->
                    a.text(request.text)
                        .apply {
                            request.analyzer?.let { analyzer(it) }
                            request.tokenizer?.let { tokenizer { t -> t.name(it) } }
                            request.filter?.let { filter(it) }
                            request.charFilter?.let { charFilter(it) }
                        }
                }
            }

        val tokens =
            response.tokens().map { token ->
                AnalyzeToken(
                    token = token.token(),
                    startOffset = token.startOffset().toInt(),
                    endOffset = token.endOffset().toInt(),
                    type = token.type(),
                    position = token.position().toInt(),
                )
            }

        return AnalyzeResponse(tokens = tokens)
    }

    // ── 매핑 조회 ─────────────────────────────────────────────────────────

    fun getMapping(
        clusterId: String,
        indexName: String,
    ): IndexMappingResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.indices().getMapping { it.index(indexName) }
        val mappingRecord = response.mappings()[indexName]

        @Suppress("UNCHECKED_CAST")
        val mappingsMap = mappingRecord?.properties()?.mapValues { (_, prop) -> prop.toString() } ?: emptyMap()

        return IndexMappingResponse(index = indexName, mappings = mappingsMap)
    }

    // ── 설정 조회 ─────────────────────────────────────────────────────────

    fun getSettings(
        clusterId: String,
        indexName: String,
    ): IndexSettingsResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.indices().getSettings { it.index(indexName) }
        val settings = response.result()

        @Suppress("UNCHECKED_CAST")
        val settingsMap = settings[indexName]?.settings()?.toString()?.let { mapOf("raw" to it) } ?: emptyMap()

        return IndexSettingsResponse(index = indexName, settings = settingsMap)
    }
}

// 확장 함수: Map을 ES Query JSON 리더로 변환
private fun Map<String, Any>.toJsonReader(): java.io.Reader {
    val json = com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(this)
    return java.io.StringReader(json)
}

package com.cowave.search.template.service

import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.template.dto.ComponentTemplateInfo
import com.cowave.search.template.dto.IndexTemplateInfo
import com.cowave.search.template.dto.PutComponentTemplateRequest
import com.cowave.search.template.dto.PutIndexTemplateRequest
import com.cowave.search.template.dto.SYSTEM_TEMPLATE_PREFIXES
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class TemplateService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(TemplateService::class.java)

    // ── Composable Index Template CRUD ────────────────────────────────────

    fun listIndexTemplates(
        clusterId: String,
        name: String? = null,
        excludeSystem: Boolean = true,
    ): List<IndexTemplateInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.indices().getIndexTemplate { req -> name?.let { req.name(it) } ?: req }
            response.indexTemplates()
                .filter { tmpl ->
                    !excludeSystem || SYSTEM_TEMPLATE_PREFIXES.none { prefix -> tmpl.name().startsWith(prefix) }
                }.map { tmpl ->
                    val tpl = tmpl.indexTemplate()
                    IndexTemplateInfo(
                        name = tmpl.name(),
                        indexPatterns = tpl.indexPatterns(),
                        priority = tpl.priority()?.toInt(),
                        version = tpl.version(),
                        composedOf = tpl.composedOf(),
                        mappings = tpl.template()?.mappings()?.toString()?.let { mapOf("raw" to it) },
                        settings = tpl.template()?.settings()?.toString()?.let { mapOf("raw" to it) },
                        dataStream = tpl.dataStream() != null,
                    )
                }
        }.getOrElse { e ->
            logger.warn("인덱스 템플릿 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getIndexTemplate(
        clusterId: String,
        name: String,
    ): IndexTemplateInfo? {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.indices().getIndexTemplate { it.name(name) }
            response.indexTemplates().firstOrNull()?.let { tmpl ->
                val tpl = tmpl.indexTemplate()
                IndexTemplateInfo(
                    name = tmpl.name(),
                    indexPatterns = tpl.indexPatterns(),
                    priority = tpl.priority()?.toInt(),
                    version = tpl.version(),
                    composedOf = tpl.composedOf(),
                    mappings = tpl.template()?.mappings()?.toString()?.let { mapOf("raw" to it) },
                    settings = tpl.template()?.settings()?.toString()?.let { mapOf("raw" to it) },
                    dataStream = tpl.dataStream() != null,
                )
            }
        }.getOrElse { e ->
            logger.warn("인덱스 템플릿 조회 실패 [{}/{}]: {}", clusterId, name, e.message)
            null
        }
    }

    fun putIndexTemplate(
        clusterId: String,
        name: String,
        request: PutIndexTemplateRequest,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.indices().putIndexTemplate { req ->
            req.name(name)
                .indexPatterns(request.indexPatterns)
                .apply {
                    request.priority?.let { priority(it.toLong()) }
                    request.version?.let { version(it) }
                    if (request.composedOf.isNotEmpty()) composedOf(request.composedOf)
                    if (request.mappings != null || request.settings != null) {
                        template { t ->
                            request.mappings?.let { m ->
                                t.withJson(m.toJsonReader())
                            }
                            t
                        }
                    }
                }
        }
        logger.info("인덱스 템플릿 저장: {}/{}", clusterId, name)
    }

    fun deleteIndexTemplate(
        clusterId: String,
        name: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.indices().deleteIndexTemplate { it.name(name) }
        logger.info("인덱스 템플릿 삭제: {}/{}", clusterId, name)
    }

    // ── Component Template CRUD ───────────────────────────────────────────

    fun listComponentTemplates(
        clusterId: String,
        name: String? = null,
        excludeSystem: Boolean = true,
    ): List<ComponentTemplateInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.cluster().getComponentTemplate { req -> name?.let { req.name(it) } ?: req }

            // 어떤 인덱스 템플릿이 각 컴포넌트를 사용하는지 역추적
            val indexTemplates =
                runCatching {
                    client.indices().getIndexTemplate { }.indexTemplates()
                }.getOrElse { emptyList() }

            response.componentTemplates()
                .filter { tmpl ->
                    !excludeSystem || SYSTEM_TEMPLATE_PREFIXES.none { prefix -> tmpl.name().startsWith(prefix) }
                }.map { tmpl ->
                    val ct = tmpl.componentTemplate()
                    val usedBy =
                        indexTemplates
                            .filter { it.indexTemplate().composedOf().contains(tmpl.name()) }
                            .map { it.name() }
                    ComponentTemplateInfo(
                        name = tmpl.name(),
                        version = ct.version(),
                        mappings = ct.template().mappings()?.toString()?.let { mapOf("raw" to it) },
                        settings = ct.template().settings()?.toString()?.let { mapOf("raw" to it) },
                        usedBy = usedBy,
                    )
                }
        }.getOrElse { e ->
            logger.warn("컴포넌트 템플릿 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun putComponentTemplate(
        clusterId: String,
        name: String,
        request: PutComponentTemplateRequest,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.cluster().putComponentTemplate { req ->
            req.name(name)
                .apply { request.version?.let { version(it) } }
                .template { t ->
                    request.mappings?.let { t.withJson(it.toJsonReader()) }
                    t
                }
        }
        logger.info("컴포넌트 템플릿 저장: {}/{}", clusterId, name)
    }

    fun deleteComponentTemplate(
        clusterId: String,
        name: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.cluster().deleteComponentTemplate { it.name(name) }
        logger.info("컴포넌트 템플릿 삭제: {}/{}", clusterId, name)
    }
}

private fun Map<String, Any>.toJsonReader(): java.io.Reader {
    val json = com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(this)
    return java.io.StringReader(json)
}

