package com.cowave.search.indices.service

import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch.core.search.SourceConfig
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.indices.dto.AnalyzeRequest
import com.cowave.search.indices.dto.AnalyzeResponse
import com.cowave.search.indices.dto.AnalyzeToken
import com.cowave.search.indices.dto.DocumentSearchRequest
import com.cowave.search.indices.dto.DocumentSearchResponse
import com.cowave.search.indices.dto.IndexInfo
import com.cowave.search.indices.dto.IndexMappingResponse
import com.cowave.search.indices.dto.IndexSettingsResponse
import com.cowave.search.indices.dto.OpenPitResponse
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class IndicesService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(IndicesService::class.java)

    // ── 인덱스 목록 조회 ──────────────────────────────────────────────────

    fun listIndices(
        clusterId: String,
        pattern: String = "*",
        excludeSystem: Boolean = true,
    ): List<IndexInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val statsResponse = client.indices().stats { it.index(pattern) }
            val aliasResponse =
                runCatching {
                    client.indices().getAlias { it.index(pattern) }
                }.getOrNull()

            statsResponse.indices()?.mapNotNull { (indexName, indexStats) ->
                if (excludeSystem && indexName.startsWith(".")) return@mapNotNull null

                val aliases =
                    aliasResponse
                        ?.aliases()
                        ?.get(indexName)
                        ?.aliases()
                        ?.keys
                        ?.toList() ?: emptyList()

                IndexInfo(
                    name = indexName,
                    health = null,
                    status = null,
                    docsCount = indexStats.total()?.docs()?.count(),
                    storeSizeBytes = indexStats.total()?.store()?.sizeInBytes(),
                    primaryShards = null,
                    replicaShards = null,
                    aliases = aliases,
                )
            } ?: emptyList()
        }.getOrElse { e ->
            logger.warn("인덱스 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    // ── 문서 조회 (Search After + PIT) ───────────────────────────────────

    fun searchDocuments(
        clusterId: String,
        indexName: String,
        request: DocumentSearchRequest,
    ): DocumentSearchResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            client.search(
                { s ->
                    s.index(indexName)
                        .size(request.size)
                        .source(SourceConfig.of { it.fetch(true) })
                        .apply {
                            if (request.pitId != null) {
                                pit { p -> p.id(request.pitId).keepAlive { t -> t.time("1m") } }
                            } else {
                                from(request.from)
                            }
                            request.query?.let { q ->
                                query { qb -> qb.withJson(q.toJsonReader()) }
                            }
                            if (request.sort != null) {
                                request.sort.forEach { sortItem ->
                                    sortItem.forEach { (field, order) ->
                                        sort { so ->
                                            so.field { f ->
                                                f.field(field)
                                                    .order(
                                                        if (order.toString().uppercase() == "DESC") {
                                                            SortOrder.Desc
                                                        } else {
                                                            SortOrder.Asc
                                                        },
                                                    )
                                            }
                                        }
                                    }
                                }
                            }
                            request.searchAfter?.let { sa ->
                                searchAfter(
                                    sa.map { v ->
                                        co.elastic.clients.elasticsearch._types.FieldValue.of(v.toString())
                                    },
                                )
                            }
                        }
                },
                Map::class.java,
            )

        val hits = response.hits().hits()
        val documents =
            hits.map { hit ->
                @Suppress("UNCHECKED_CAST")
                (hit.source() as? Map<String, Any?> ?: emptyMap<String, Any?>()).plus("_id" to hit.id())
            }
        val lastSearchAfter = hits.lastOrNull()?.sort()?.map { it._get() }

        return DocumentSearchResponse(
            total = response.hits().total()?.value() ?: 0L,
            hits = documents,
            pitId = response.pitId(),
            searchAfter = lastSearchAfter,
        )
    }

    // ── PIT 관리 ─────────────────────────────────────────────────────────

    fun openPit(
        clusterId: String,
        indexName: String,
        keepAlive: String = "5m",
    ): OpenPitResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.openPointInTime { it.index(indexName).keepAlive { t -> t.time(keepAlive) } }
        return OpenPitResponse(pitId = response.id())
    }

    fun closePit(
        clusterId: String,
        pitId: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        runCatching {
            client.closePointInTime { it.id(pitId) }
        }.onFailure { e ->
            logger.warn("PIT 닫기 실패 [{}]: {}", pitId, e.message)
        }
    }

    // ── 분석기 실행 ───────────────────────────────────────────────────────

    fun analyze(
        clusterId: String,
        request: AnalyzeRequest,
    ): AnalyzeResponse {
        val client = clientFactory.getClient(clusterId)

        val response =
            if (request.index != null) {
                client.indices().analyze { a ->
                    a.index(request.index)
                        .text(request.text)
                        .apply {
                            request.analyzer?.let { analyzer(it) }
                            request.tokenizer?.let { tokenizer { t -> t.name(it) } }
                            request.filter?.let { filter(it.map { f -> co.elastic.clients.elasticsearch.indices.AnalyzeToken.of { t -> t.name(f) } }) }
                            request.charFilter?.let { charFilter(it.map { f -> co.elastic.clients.elasticsearch.indices.AnalyzeToken.of { t -> t.name(f) } }) }
                        }
                }
            } else {
                client.indices().analyze { a ->
                    a.text(request.text)
                        .apply {
                            request.analyzer?.let { analyzer(it) }
                            request.tokenizer?.let { tokenizer { t -> t.name(it) } }
                            request.filter?.let { filter(it.map { f -> co.elastic.clients.elasticsearch.indices.AnalyzeToken.of { t -> t.name(f) } }) }
                            request.charFilter?.let { charFilter(it.map { f -> co.elastic.clients.elasticsearch.indices.AnalyzeToken.of { t -> t.name(f) } }) }
                        }
                }
            }

        val tokens =
            response.tokens().map { token ->
                AnalyzeToken(
                    token = token.token(),
                    startOffset = token.startOffset().toInt(),
                    endOffset = token.endOffset().toInt(),
                    type = token.type(),
                    position = token.position().toInt(),
                )
            }

        return AnalyzeResponse(tokens = tokens)
    }

    // ── 매핑 조회 ─────────────────────────────────────────────────────────

    fun getMapping(
        clusterId: String,
        indexName: String,
    ): IndexMappingResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.indices().getMapping { it.index(indexName) }
        val mappingRecord = response.mappings()[indexName]

        @Suppress("UNCHECKED_CAST")
        val mappingsMap = mappingRecord?.properties()?.mapValues { (_, prop) -> prop.toString() } ?: emptyMap()

        return IndexMappingResponse(index = indexName, mappings = mappingsMap)
    }

    // ── 설정 조회 ─────────────────────────────────────────────────────────

    fun getSettings(
        clusterId: String,
        indexName: String,
    ): IndexSettingsResponse {
        val client = clientFactory.getClient(clusterId)
        val response = client.indices().getSettings { it.index(indexName) }
        val settings = response.result()

        @Suppress("UNCHECKED_CAST")
        val settingsMap = settings[indexName]?.settings()?.toString()?.let { mapOf("raw" to it) } ?: emptyMap()

        return IndexSettingsResponse(index = indexName, settings = settingsMap)
    }
}

// 확장 함수: Map을 ES Query JSON 리더로 변환
private fun Map<String, Any>.toJsonReader(): java.io.Reader {
    val json = com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(this)
    return java.io.StringReader(json)
}

