package com.cowave.search.pipeline.service

import co.elastic.clients.elasticsearch.ingest.Document
import co.elastic.clients.elasticsearch.ingest.Processor
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.pipeline.dto.PipelineInfo
import com.cowave.search.pipeline.dto.ProcessorResult
import com.cowave.search.pipeline.dto.PutPipelineRequest
import com.cowave.search.pipeline.dto.SimulateDocResult
import com.cowave.search.pipeline.dto.SimulatePipelineRequest
import com.cowave.search.pipeline.dto.SimulatePipelineResponse
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class PipelineService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(PipelineService::class.java)

    fun listPipelines(
        clusterId: String,
        id: String? = null,
    ): List<PipelineInfo> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.ingest().getPipeline { req -> id?.let { req.id(it) } ?: req }
            response.pipelines().map { (pipelineId, pipeline) ->
                val processors =
                    pipeline.processors().map { proc ->
                        mapOf("type" to proc._kind().jsonValue())
                    }
                PipelineInfo(
                    id = pipelineId,
                    description = pipeline.description(),
                    version = pipeline.version(),
                    processors = processors,
                )
            }
        }.getOrElse { e ->
            logger.warn("파이프라인 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getPipeline(
        clusterId: String,
        id: String,
    ): PipelineInfo? {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.ingest().getPipeline { it.id(id) }
            response.pipelines()[id]?.let { pipeline ->
                PipelineInfo(
                    id = id,
                    description = pipeline.description(),
                    version = pipeline.version(),
                    processors = pipeline.processors().map { mapOf("type" to it._kind().jsonValue()) },
                )
            }
        }.getOrElse { e ->
            logger.warn("파이프라인 조회 실패 [{}/{}]: {}", clusterId, id, e.message)
            null
        }
    }

    fun putPipeline(
        clusterId: String,
        id: String,
        request: PutPipelineRequest,
    ) {
        val client = clientFactory.getClient(clusterId)
        val mapper = com.fasterxml.jackson.databind.ObjectMapper()

        client.ingest().putPipeline { req ->
            req.id(id)
                .apply {
                    request.description?.let { description(it) }
                    request.version?.let { version(it) }
                    if (request.processors.isNotEmpty()) {
                        processors(
                            request.processors.map { procMap ->
                                val procJson = mapper.writeValueAsString(procMap)
                                Processor.of { p ->
                                    p.withJson(java.io.StringReader(procJson))
                                }
                            },
                        )
                    }
                }
        }
        logger.info("파이프라인 저장: {}/{}", clusterId, id)
    }

    fun deletePipeline(
        clusterId: String,
        id: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.ingest().deletePipeline { it.id(id) }
        logger.info("파이프라인 삭제: {}/{}", clusterId, id)
    }

    fun simulatePipeline(
        clusterId: String,
        pipelineId: String?,
        request: SimulatePipelineRequest,
    ): SimulatePipelineResponse {
        val client = clientFactory.getClient(clusterId)
        val mapper = com.fasterxml.jackson.databind.ObjectMapper()

        // ES 9.x: client.simulate().ingest() API 사용
        val docs =
            request.docs.map { doc ->
                val sourceJson = mapper.writeValueAsString(doc.source)
                Document.of { d ->
                    d.index(doc.index)
                        .apply { doc.id?.let { id(it) } }
                        .withJson(java.io.StringReader(sourceJson))
                }
            }

        val response =
            client.simulate().ingest { req ->
                pipelineId?.let { req.pipeline(it) }
                req.docs(docs)
            }

        val results =
            response.docs().map { docResult ->
                val docSim = docResult.doc()
                val error = docSim?.error()
                if (error != null) {
                    SimulateDocResult(
                        docId = docSim.id(),
                        index = docSim.index(),
                        source = emptyMap(),
                        error = error.reason(),
                    )
                } else {
                    @Suppress("UNCHECKED_CAST")
                    val source = docSim?.source()?.mapValues { (_, v) -> v.to(Any::class.java) } ?: emptyMap()
                    SimulateDocResult(
                        docId = docSim?.id(),
                        index = docSim?.index(),
                        source = source,
                        processorResults = emptyList(),
                    )
                }
            }

        return SimulatePipelineResponse(docs = results)
    }
}

package com.cowave.search.documentanalysis.service

import co.elastic.clients.elasticsearch._types.FieldValue
import co.elastic.clients.elasticsearch._types.SortOrder
import com.cowave.search.common.elasticsearch.ElasticsearchClientFactory
import com.cowave.search.documentanalysis.dto.ExecuteQueryRequest
import com.cowave.search.documentanalysis.dto.ExecuteQueryResponse
import com.cowave.search.documentanalysis.dto.FieldStatistics
import com.cowave.search.documentanalysis.dto.FieldTermVector
import com.cowave.search.documentanalysis.dto.SaveQueryRequest
import com.cowave.search.documentanalysis.dto.SavedQuery
import com.cowave.search.documentanalysis.dto.TermInfo
import com.cowave.search.documentanalysis.dto.TermVectorRequest
import com.cowave.search.documentanalysis.dto.TermVectorResponse
import com.cowave.search.documentanalysis.dto.TokenInfo
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.time.Instant

@Service
class DocumentAnalysisService(
    private val clientFactory: ElasticsearchClientFactory,
) {
    private val logger = LoggerFactory.getLogger(DocumentAnalysisService::class.java)

    // ── Term Vector 분석 ──────────────────────────────────────────────────

    fun getTermVector(
        clusterId: String,
        request: TermVectorRequest,
    ): TermVectorResponse {
        val client = clientFactory.getClient(clusterId)

        val tvRequest =
            co.elastic.clients.elasticsearch.core.TermvectorsRequest.Builder<Map<*, *>>()
                .index(request.index)
                .termStatistics(request.termStatistics)
                .fieldStatistics(request.fieldStatistics)
                .positions(request.positions)
                .offsets(request.offsets)
                .payloads(request.payloads)
                .also { b ->
                    request.id?.let { b.id(it) }
                    request.fields?.let { b.fields(it) }
                }.build()

        val response = client.termvectors(tvRequest)

        val termVectors =
            response.termVectors().entries.associate { (fieldName, fieldVector) ->
                val fieldStats =
                    fieldVector.fieldStatistics()?.let { fs ->
                        FieldStatistics(
                            docCount = fs.docCount().toLong(),
                            sumDocFreq = fs.sumDocFreq(),
                            sumTtf = fs.sumTtf(),
                        )
                    }
                val terms =
                    fieldVector.terms().entries.associate { (termName, termStats) ->
                        val tokens =
                            termStats.tokens().map { token ->
                                TokenInfo(
                                    position = token.position(),
                                    startOffset = token.startOffset(),
                                    endOffset = token.endOffset(),
                                    payload = token.payload(),
                                )
                            }
                        termName to
                            TermInfo(
                                docFreq = termStats.docFreq()?.toLong(),
                                ttf = termStats.ttf()?.toLong(),
                                termFreq = termStats.termFreq().toLong(),
                                score = termStats.score(),
                                tokens = tokens,
                            )
                    }
                fieldName to FieldTermVector(fieldStatistics = fieldStats, terms = terms)
            }

        return TermVectorResponse(
            index = response.index(),
            id = response.id(),
            found = response.found(),
            termVectors = termVectors,
        )
    }

    // ── 검색 쿼리 저장 (dsearch-analysis-query 인덱스) ────────────────────

    fun saveQuery(
        clusterId: String,
        request: SaveQueryRequest,
    ): String {
        val client = clientFactory.getClient(clusterId)
        val query =
            SavedQuery(
                id = null,
                name = request.name,
                description = request.description,
                index = request.index,
                query = request.query,
            )
        val response = client.index { it.index(ANALYSIS_QUERY_INDEX).document(query) }
        logger.info("검색 쿼리 저장 [{}/{}]: {}", clusterId, response.id(), request.name)
        return response.id()
    }

    fun listSavedQueries(
        clusterId: String,
        size: Int = 20,
        searchAfterValues: List<String>? = null,
    ): List<SavedQuery> {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response =
                client.search(
                    { s ->
                        s.index(ANALYSIS_QUERY_INDEX)
                            .size(size)
                            .sort { so -> so.field { f -> f.field("updatedAt").order(SortOrder.Desc) } }
                            .apply {
                                searchAfterValues?.let { sa ->
                                    searchAfter(sa.map { FieldValue.of(it) })
                                }
                            }
                    },
                    SavedQuery::class.java,
                )
            response.hits().hits().mapNotNull { hit ->
                hit.source()?.copy(id = hit.id())
            }
        }.getOrElse { e ->
            logger.warn("저장된 쿼리 목록 조회 실패 [{}]: {}", clusterId, e.message)
            emptyList()
        }
    }

    fun getSavedQuery(
        clusterId: String,
        id: String,
    ): SavedQuery? {
        val client = clientFactory.getClient(clusterId)
        return runCatching {
            val response = client.get({ it.index(ANALYSIS_QUERY_INDEX).id(id) }, SavedQuery::class.java)
            response.source()?.copy(id = response.id())
        }.getOrElse { e ->
            logger.warn("저장된 쿼리 조회 실패 [{}/{}]: {}", clusterId, id, e.message)
            null
        }
    }

    fun deleteSavedQuery(
        clusterId: String,
        id: String,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.delete { it.index(ANALYSIS_QUERY_INDEX).id(id) }
        logger.info("저장된 쿼리 삭제: {}/{}", clusterId, id)
    }

    fun updateSavedQuery(
        clusterId: String,
        id: String,
        request: SaveQueryRequest,
    ) {
        val client = clientFactory.getClient(clusterId)
        client.update(
            {
                it.index(ANALYSIS_QUERY_INDEX)
                    .id(id)
                    .doc(
                        mapOf(
                            "name" to request.name,
                            "description" to request.description,
                            "index" to request.index,
                            "query" to request.query,
                            "updatedAt" to Instant.now(),
                        ),
                    )
            },
            SavedQuery::class.java,
        )
        logger.info("저장된 쿼리 수정: {}/{}", clusterId, id)
    }

    // ── 검색 쿼리 실행 ────────────────────────────────────────────────────

    fun executeQuery(
        clusterId: String,
        request: ExecuteQueryRequest,
    ): ExecuteQueryResponse {
        val client = clientFactory.getClient(clusterId)
        val queryJson = com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(request.query)

        val response =
            client.search(
                { s ->
                    s.index(request.index)
                        .size(request.size)
                        .from(request.from)
                        .query { q -> q.withJson(java.io.StringReader(queryJson)) }
                },
                Map::class.java,
            )

        @Suppress("UNCHECKED_CAST")
        val hits =
            response.hits().hits().map { hit ->
                (hit.source() as? Map<String, Any?> ?: emptyMap<String, Any?>()).plus("_id" to hit.id())
            }

        return ExecuteQueryResponse(
            total = response.hits().total()?.value() ?: 0L,
            took = response.took(),
            hits = hits,
        )
    }

    companion object {
        const val ANALYSIS_QUERY_INDEX = "dsearch-analysis-query"
    }
}

