        @RequestBody request: TermVectorRequest,
    ): TermVectorResponse = documentAnalysisService.getTermVector(clusterId, request)

    // ── 검색 쿼리 실행 ─────────────────────────────────────────────────────

    @PostMapping("/execute")
    fun executeQuery(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: ExecuteQueryRequest,
    ): ExecuteQueryResponse = documentAnalysisService.executeQuery(clusterId, request)

    // ── 검색 쿼리 저장/관리 ───────────────────────────────────────────────

    @GetMapping("/queries")
    fun listSavedQueries(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
    ): List<SavedQuery> {
        val searchAfter = cursor?.split(",")
        return documentAnalysisService.listSavedQueries(clusterId, size, searchAfter)
    }

    @PostMapping("/queries")
    @ResponseStatus(HttpStatus.CREATED)
    fun saveQuery(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: SaveQueryRequest,
    ): Map<String, String> {
        val id = documentAnalysisService.saveQuery(clusterId, request)
        return mapOf("id" to id)
    }

    @GetMapping("/queries/{id}")
    fun getSavedQuery(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ): ResponseEntity<SavedQuery> {
        val query = documentAnalysisService.getSavedQuery(clusterId, id)
        return if (query != null) ResponseEntity.ok(query) else ResponseEntity.notFound().build()
    }

    @PutMapping("/queries/{id}")
    fun updateSavedQuery(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
        @RequestBody request: SaveQueryRequest,
    ): ResponseEntity<Void> {
        documentAnalysisService.updateSavedQuery(clusterId, id, request)
        return ResponseEntity.ok().build()
    }

    @DeleteMapping("/queries/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun deleteSavedQuery(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ) {
        documentAnalysisService.deleteSavedQuery(clusterId, id)
    }
}

package com.cowave.search.config

import org.springframework.boot.context.properties.ConfigurationProperties
import org.springframework.boot.context.properties.EnableConfigurationProperties
import org.springframework.context.annotation.Configuration

@Configuration
@EnableConfigurationProperties(RateLimitProperties::class)
class RateLimitConfig

@ConfigurationProperties(prefix = "dsearch.rate-limit")
data class RateLimitProperties(
    /** Rate Limiting 활성화 여부 */
    val enabled: Boolean = true,
    /** 시간 창 (초) */
    val windowSeconds: Long = 60,
    /** 시간 창 내 최대 요청 수 (클러스터+IP 조합 기준) */
    val maxRequests: Int = 300,
    /** Rate Limit 적용 경로 패턴 */
    val paths: List<String> =
        listOf(
            "/indices/**",
            "/templates/**",
            "/pipelines/**",
            "/document-analysis/**",
        ),
)

package com.cowave.search.config

import com.fasterxml.jackson.databind.ObjectMapper
import jakarta.servlet.FilterChain
import jakarta.servlet.http.HttpServletRequest
import jakarta.servlet.http.HttpServletResponse
import org.slf4j.LoggerFactory
import org.springframework.http.HttpStatus
import org.springframework.http.MediaType
import org.springframework.stereotype.Component
import org.springframework.util.AntPathMatcher
import org.springframework.web.filter.OncePerRequestFilter
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicInteger

/**
 * Caffeine 없이 ConcurrentHashMap 기반 슬라이딩 윈도우 Rate Limiter.
 *
 * 키: "{clusterId}:{clientIp}" 조합
 * 윈도우: windowSeconds 기간 내 maxRequests 초과 시 429 응답
 */
@Component
class RateLimitFilter(
    private val rateLimitProperties: RateLimitProperties,
    private val objectMapper: ObjectMapper,
) : OncePerRequestFilter() {
    private val log = LoggerFactory.getLogger(RateLimitFilter::class.java)
    private val pathMatcher = AntPathMatcher()

    // 키 → RequestBucket (요청 횟수 + 윈도우 시작 시각)
    private val buckets = ConcurrentHashMap<String, RequestBucket>()

    override fun doFilterInternal(
        request: HttpServletRequest,
        response: HttpServletResponse,
        filterChain: FilterChain,
    ) {
        if (!rateLimitProperties.enabled || !isRateLimitedPath(request.requestURI)) {
            filterChain.doFilter(request, response)
            return
        }

        val clusterId = request.getHeader("cluster-id") ?: "unknown"
        val clientIp = getClientIp(request)
        val key = "$clusterId:$clientIp"

        if (isRateLimitExceeded(key)) {
            log.warn("Rate limit exceeded: key={}", key)
            response.status = HttpStatus.TOO_MANY_REQUESTS.value()
            response.contentType = MediaType.APPLICATION_JSON_VALUE
            response.writer.write(
                objectMapper.writeValueAsString(
                    mapOf(
                        "error" to "Too Many Requests",
                        "message" to "요청 한도를 초과했습니다. ${rateLimitProperties.windowSeconds}초 후 다시 시도하세요.",
                        "limit" to rateLimitProperties.maxRequests,
                        "windowSeconds" to rateLimitProperties.windowSeconds,
                    ),
                ),
            )
            return
        }

        filterChain.doFilter(request, response)
    }

    private fun isRateLimitExceeded(key: String): Boolean {
        val now = Instant.now().epochSecond
        val windowStart = now - rateLimitProperties.windowSeconds

        val bucket =
            buckets.compute(key) { _, existing ->
                when {
                    existing == null -> RequestBucket(AtomicInteger(1), now)
                    existing.windowStartSec < windowStart -> RequestBucket(AtomicInteger(1), now)
                    else -> existing.also { it.count.incrementAndGet() }
                }
            }!!

        return bucket.count.get() > rateLimitProperties.maxRequests
    }

    private fun isRateLimitedPath(uri: String): Boolean = rateLimitProperties.paths.any { pattern -> pathMatcher.match(pattern, uri) }

    private fun getClientIp(request: HttpServletRequest): String =
        request
            .getHeader("X-Forwarded-For")
            ?.split(",")
            ?.firstOrNull()
            ?.trim()
            ?: request.getHeader("X-Real-IP")
            ?: request.remoteAddr

    private data class RequestBucket(
        val count: AtomicInteger,
        val windowStartSec: Long,
    )
}
